mapper.insert:
INSERT INTO intent_fewshot_sample (
    query_text, intent_code, example_json, dimension, embedding, status, create_time, update_time
) VALUES (
    #{queryText}, #{intentCode}, #{exampleJson}, #{dimension}, #{embedding}, #{status},
    #{createTime}, #{updateTime}
)

mapper.update:
UPDATE intent_fewshot_sample
SET status = 0, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, query_text, intent_code, example_json, dimension, embedding, status, create_time, update_time
FROM intent_fewshot_sample
WHERE id = #{id}

SELECT COUNT(*)
FROM intent_fewshot_sample
WHERE intent_code = #{intentCode} AND status = #{status}
